import XCTest
@testable import CryptoResearch
final class CommunityTests:XCTestCase {
 let now:Int64=1800000000000
 func p(_ id:String,_ title:String,_ at:Int64,_ source:String="COINPAN")->CommunityPost{CommunityPost(source:source,id:id,title:title,url:"",published_ms:at)}
 func d(_ posts:[CommunityPost])->CommunityDataset{CommunityDataset(posts:posts,synthetic:false,collected:now,origin:"fixture")}
 func testSampleAndCoinFilter(){let sample=CommunityCore.sample(now),a=CommunityCore.analyze(sample,"전체",24,now);XCTAssertEqual(a.posts.count,3);XCTAssertEqual(a.up,1);XCTAssertEqual(a.down,1);XCTAssertEqual(a.mixed,1);XCTAssertEqual(CommunityCore.analyze(sample,"BTC",24,now).posts.count,1);XCTAssertTrue(CommunityCore.summary(a).contains("실제 커뮤니티 자료 아님"))}
 func testWindowsAndFuture(){let a=CommunityCore.analyze(d([p("1","BTC 상승",now-25*3600000),p("2","ETH 상승",now+1),p("3","점심",now-1)]),"전체",24,now);XCTAssertEqual(a.outside,2);XCTAssertEqual(a.irrelevant,1);XCTAssertTrue(a.posts.isEmpty);XCTAssertEqual(CommunityCore.analyze(d([p("4","BTC 상승",now-25*3600000)]),"전체",168,now).posts.count,1)}
 func testDuplicateNormalization(){let a=CommunityCore.analyze(d([p("1","BTC 상승!",now),p("2","btc 상승",now-1,"DCINSIDE"),p("1","ETH 하락",now-2)]),"전체",24,now);XCTAssertEqual(a.posts.count,1);XCTAssertEqual(a.duplicates,2)}
 func testBoundariesAndNeutral(){let a=CommunityCore.analyze(d([p("1","solidity 개발",now),p("2","BTC 토론",now)]),"전체",24,now);XCTAssertEqual(a.posts.count,1);XCTAssertEqual(a.neutral,1)}
 func testURLGuards(){XCTAssertTrue(CommunityCore.safeURL("COINPAN","https://coinpan.com/free/1"));for s in ["javascript:alert(1)","http://coinpan.com/free","https://coinpan.com.evil.com/","https://user@coinpan.com/","https://coinpan.com:8080/"]{XCTAssertFalse(CommunityCore.safeURL("COINPAN",s))};XCTAssertFalse(CommunityCore.safeURL("DCINSIDE","https://gall.dcinside.com/board/view/?id=other&no=1"))}
 func testJSONStrictness()throws{let input:[String:Any]=["community_schema_version":1,"synthetic":false,"collected_ms":now,"posts":[["source":"COINPAN","id":"1","title":"비트코인 상승","url":"","published_ms":now-1]]];let data=try JSONSerialization.data(withJSONObject:input);XCTAssertEqual(try CommunityCore.parse(data,now).posts.count,1);XCTAssertThrowsError(try CommunityCore.parse(data,now-1));XCTAssertThrowsError(try CommunityCore.parse(Data(repeating:0,count:1048577),now));XCTAssertThrowsError(try CommunityCore.parse(Data([255]),now))}
 func testHTMLParser()throws{let html="<tr class='ub-content' data-no='123'><td class='gall_tit'><a href='/board/view/?id=bitcoins_new1&amp;no=123'><em>BTC</em> 상승 &amp; 토론</a></td><td class='gall_date' title='2026-10-30 09:00:00'>09:00</td></tr>";let parsed=try CommunityCore.dcHTML(html,now);XCTAssertEqual(parsed.posts.first?.title,"BTC 상승 & 토론");let date=ISO8601DateFormatter().date(from:"2026-10-30T00:00:00Z")!;XCTAssertEqual(parsed.posts.first?.published_ms,Int64(date.timeIntervalSince1970*1000));XCTAssertThrowsError(try CommunityCore.dcHTML("<html>captcha</html>",now))}
 func testExportIsNotSignal()throws{let a=CommunityCore.analyze(CommunityCore.sample(now),"전체",24,now);let j=try XCTUnwrap(JSONSerialization.jsonObject(with:CommunityCore.report(a)) as? [String:Any]);XCTAssertEqual(j["trading_signal"] as? Bool,false);XCTAssertEqual(j["synthetic"] as? Bool,true);XCTAssertNil(j["posts"]);XCTAssertEqual(j["sample_count"] as? Int,3)}
 func testNoDataHasNoSentimentScore()throws{let a=CommunityCore.analyze(d([]),"BTC",24,now);XCTAssertTrue(a.posts.isEmpty);let j=try XCTUnwrap(JSONSerialization.jsonObject(with:CommunityCore.report(a)) as? [String:Any]);XCTAssertNil(j["sentiment_score"])}
 @MainActor func testStoreStartsOffline(){let store=CommunityStore();XCTAssertNil(store.dataset);XCTAssertFalse(store.busy);store.cancel()}
}
